  if(color)r.fills=[{type:'SOLID',color:color,opacity:opacity??1}]; else r.fills=[];
  if(radius)r.cornerRadius=radius; p.appendChild(r); return r;
}
function cv(hex,op){return {type:'SOLID',color:{r:parseInt(hex.slice(1,3),16)/255,g:parseInt(hex.slice(3,5),16)/255,b:parseInt(hex.slice(5,7),16)/255},opacity:op??1};}
function clonePlace(id,parent,x,y,scale){
  const n=figma.getNodeById(id); if(!n)return null;
  const c=n.clone(); c.x=x; c.y=y;
  if(scale){c.resize(Math.round(n.width*scale),Math.round(n.height*scale));}
  parent.appendChild(c); return c;
}

