const ISOL={r:0x2B/255,g:0x2D/255,b:0x33/255};
const MUTED={r:0x8A/255,g:0x90/255,b:0x99/255};
async function T(p,name,x,y,str,size,color,weight,align){
  const t=figma.createText(); t.name=name; t.x=x; t.y=y;
  t.characters=str; t.fontName={family:'Nunito',style:weight||'Regular'}; t.fontSize=size;
  t.fills=[{type:'SOLID',color:color}]; if(align)t.textAlignHorizontal=align;
  p.appendChild(t); return t;
}
function R(p,name,x,y,w,h,color,opacity,radius){
  const r=figma.createRectangle(); r.name=name; r.resize(w,h); r.x=x; r.y=y;
  if(color)r.fills=[{type:'SOLID',color:color,opacity:opacity??1}]; else r.fills=[];
  if(radius)r.cornerRadius=radius; p.appendChild(r); return r;
}
function makeIndicator(activeIdx,x,y){
  const g=figma.createFrame(); g.name='PageIndicator'; g.resize(56,8); g.x=x; g.y=y; g.fills=[];
  for(let i=0;i<3;i++){
    const d=figma.createEllipse(); d.name='Dot'+(i+1); d.resize(8,8); d.x=i*24; d.y=0;
    d.fills=[{type:'SOLID',color:i===activeIdx?ISOL:{r:0.86,g:0.87,b:0.89}}];
    g.appendChild(d);
  }
  return g;
}

